   "සූත්‍රාර්ථය: බ්‍යඤ්ජනෙ පරෙ, ව්‍යඤ්ජනයා පරකල්හි; සරා ඛො, ස්වරයෝ; ක්වචි, කිසි තැනෙක්හි; ලොපං පප්පොන්ති, ලෝපයට පැමිණෙති; තත්‍ර ලුත්තෙ ඨානෙ, ඒ ලොප් වූ ස්ථානයෙහි; අකාරො ච, අකාරයෙක් ද; හොති, ආගම වේ."
